class Task:
    def __init__(self, id, C, T, D=None):
        self.id = id
        self.C = C
        self.T = T
        self.D = D if D is not None else T # Implicit deadline if not specified
        self.U = C / T

def calculate_system_utilization(task_set):
    U_sum = 0.0
    for task in task_set:
        U_sum += task.U
    return U_sum

def is_implicit_deadline_system(task_set):
    for task in task_set:
        if task.D != task.T:
            return False
    return True

class Task:
    def __init__(self, id, C, T, D=None):
        self.id = id
        self.C = C
        self.T = T
        self.D = D if D is not None else T
        self.U = C / T
        self.priority = 1.0 / T # Higher value means higher priority

def sort_tasks_by_rm_priority(task_set):
    # Sort in ascending order of period (descending order of priority)
    return sorted(task_set, key=lambda task: task.T)

class BurstyTask(Task):
    def __init__(self, id, C, T, D=None, alpha=1.0):
        super().__init__(id, C, T, D)
        self.alpha = alpha # Bursty ratio

def get_bursty_execution_time(task, is_bursty_job=False):
    if is_bursty_job:
        return task.alpha * task.C
    else:
        return task.C

class SelfSuspendingTask(Task):
    def __init__(self, id, C, T, D=None, S=0):
        super().__init__(id, C, T, D)
        self.S = S # Total suspension time
        # Check assumption: C + S <= T
        if self.C + self.S > self.T:
            raise ValueError(f"Task {self.id}: C + S must be <= T")

class DSTask(Task):
    def __init__(self, id, C, T, D=None, is_ds=False):
        super().__init__(id, C, T, D)
        self.is_deferrable_server = is_ds
        self.delta = 1 if is_ds else 0 # 1 for DS, 0 for sporadic
        # C is budget if DS, WCET if sporadic
        # T is replenishment period if DS, period if sporadic

def replenish_budget(ds_task):
    if ds_task.is_deferrable_server:
        ds_task.current_budget = ds_task.C

def is_ds_system_schedulable(ds_task_set):
    for task_k in ds_task_set:
        if task_k.delta == 0: # Sporadic task
            R_k = calculate_worst_case_response_time(task_k, ds_task_set)
            if R_k > task_k.T:
                return False # Sporadic task missed deadline
        else: # Deferrable server
            # This is a simplified check for progressiveness, actual calculation is complex
            # It implies that the DS can consume its budget C_k within T_k, considering interference
            # The analysis in the paper provides a way to check this via transformation
            if not check_ds_progressiveness(task_k, ds_task_set):
                return False # DS failed progress guarantee
    return True

class TaskC(Task):
    def __init__(self, original_task):
        super().__init__(original_task.id, original_task.C + original_task.S, original_task.T, original_task.D)
        self.original_S = original_task.S

def transform_task_k_suspension_to_computation(task_k_original):
    return TaskC(task_k_original)

def check_lemma3_contrapositive(task_k_original, higher_priority_tasks):
    task_k_C = transform_task_k_suspension_to_computation(task_k_original)
    # If task_k_C is schedulable, then task_k_original is also schedulable.
    # This is the useful direction for analysis.
    if is_schedulable_fixed_priority(task_k_C, higher_priority_tasks):
        return True # Original task_k is schedulable
    else:
        return False # Original task_k might be unschedulable

def check_theorem5_schedulability(task_set_original):
    # Assume task_set_original is already sorted by period (RM priority)
    for k_idx in range(len(task_set_original)):
        task_k_original = task_set_original[k_idx]
        higher_priority_tasks_original = task_set_original[:k_idx]

        # Use the per-task check from Theorem 4
        if not check_theorem4_schedulability(task_k_original, higher_priority_tasks_original):
            return False # If any task is not schedulable, the system is not schedulable

    return True # All tasks are schedulable
